def check_plan(plan: dict, ops: dict[str, dict], base: Path) -> list[str]:
    problems = []
    term = (plan.get("terminal") or {}).get("tool")
    contract = {"terminal_tools": [{"tool": term, "evidence": (plan.get("terminal") or {}).get("evidence") or []}]}
    problems += [f"{f.code}: {f.message}" for f in check_contract(contract, ops, base) if f.level == "error"]
    if term not in ops:
        return problems
    props, required = ops[term]["properties"], ops[term]["required"]
    for field in plan.get("fields") or {}:
        if field not in props:
            problems.append(f"field {field!r} is not a request field of {term}")
    closings = plan.get("closings") or {}
    if not closings:
        problems.append("no closings declared")
    names: dict[str, str] = {}
    for cid in closings:
        if step_name(cid) in names:
            problems.append(f"closings {names[step_name(cid)]!r} and {cid!r} would get the same step name {step_name(cid)!r}; rename one")
        names.setdefault(step_name(cid), cid)
    for cid, closing in closings.items():
        values = closing.get("set") or {}
        quotes = _quotes(closing.get("evidence") or [], base)
        if not quotes or not all(quotes):
            problems.append(f"closing {cid!r}: every evidence quote must appear in its source")
        for field, value in values.items():
            spec = props.get(field)
            if spec is None:
                problems.append(f"closing {cid!r}: {field!r} is not a request field of {term}")
            elif spec.get("enum") and value not in spec["enum"]:
                problems.append(f"closing {cid!r}: {field}={value!r} is not one of {spec['enum']}")
            elif not spec.get("enum") and not any(str(value) in q for q in quotes):
                problems.append(f"closing {cid!r}: {field}={value!r} is not enumerated by the tool API and not in its evidence")
        missing = [f for f in required if f not in values and f not in (plan.get("fields") or {})]
        if missing:
            problems.append(f"closing {cid!r}: required fields {missing} of {term} are neither set nor mapped")
    return problems


def _var(name: str, op: str, operand) -> dict:
    return {"variable": name, "operator": op, "operand": operand}


def _when(*checks: dict) -> dict:
    return {"logic": "or", "conditions": [checks[0] if len(checks) == 1 else {"logic": "and", "conditions": list(checks)}]}


def check_ladder(ladder: dict, body: dict, base: Path) -> list[str]:
    problems = []
    nodes = body.get("nodes") or {}
    template = nodes.get(ladder.get("template"))
    if not template or template.get("node_type") != "conversation" or template.get("passthrough"):
        return [f"ladder template {ladder.get('template')!r} is not a waiting conversation step of the body"]
    done = str(ladder.get("done") or "")
    if done not in nodes and not done.startswith(SYMBOL):
        problems.append(f"ladder done {done!r} is neither a body step nor a close:<id> target")
    for part, key in (("items", "count"), ("attempts", "allowed")):
        spec = ladder.get(part) or {}
        if not isinstance(spec.get("max"), int) or not 1 <= spec["max"] <= 9:
            problems.append(f"ladder {part}.max must be a whole number from 1 to 9")
        if not str(spec.get(key) or "").strip():
            problems.append(f"ladder {part}.{key} names no variable")
        quotes = _quotes(spec.get("evidence") or [], base)
        if not quotes or not all(quotes):
            problems.append(f"ladder {part}: every evidence quote must appear in its source")
    if "{i}" not in str((ladder.get("attempts") or {}).get("allowed", "")):
        problems.append("ladder attempts.allowed must contain {i}: one allowed count per item")
    refusal = str(ladder.get("refusal") or "")
    if "{i}" not in refusal or "{a}" not in refusal:
        problems.append("ladder refusal must contain {i} and {a}: one variable per item and attempt")
    if refusal not in [e.get("name") for e in template.get("extraction_schema") or []]:
        problems.append(f"the ladder template does not extract its refusal variable {refusal!r}")
    key = ladder["template"]
    written = {f"{key}_item_{i}" for i in range(1, 10)} | {f"{key}_{i}_{a}" for i in range(1, 10) for a in range(1, 10)}
    if written & set(nodes):
        problems.append(f"body steps {sorted(written & set(nodes))} use names the ladder writes")
    return problems


def expand_ladder(wf: dict, ladder: dict) -> None:
    """Replace the template step by its item and attempt steps, in place."""
    nodes = wf["nodes"]
    key, done = ladder["template"], ladder["done"]
    template = nodes.pop(key)
    items, attempts = ladder["items"]["max"], ladder["attempts"]["max"]
    count, allowed, refusal = ladder["items"]["count"], ladder["attempts"]["allowed"], ladder["refusal"]

    def step(i, a):
        return f"{key}_{i}_{a}"

    def router(i):
        return f"{key}_item_{i}"

    def after(i):
        return router(i + 1) if i < items else done

    for i in range(1, items + 1):
        nodes[router(i)] = {
            "name": router(i), "node_type": "conversation", "passthrough": True, "passthrough_default_transition": step(i, 1),
            "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True, "task_message": "Do not call a tool in this turn.",
            "transitions": [{"target_node": done, "description": f"fewer than {i} items", "condition": _when(_var(count, "less_than", i))},
                            {"target_node": step(i, 1), "description": "always", "condition": {"operator": "always"}}]}
        for a in range(1, attempts + 1):
            text = json.dumps(template).replace("{i}", str(i)).replace("{a}", str(a))
            clone = json.loads(text.replace(json.dumps(NEXT_ITEM), json.dumps(after(i))))
            said_no = _var(refusal.replace("{i}", str(i)).replace("{a}", str(a)), "equals", "yes")
            first = []
            if a < attempts:
                first.append({"target_node": step(i, a + 1), "description": f"refused attempt {a}, another attempt is allowed",
                              "condition": _when(said_no, _var(allowed.replace("{i}", str(i)), "greater_than", a))})
            first.append({"target_node": after(i), "description": f"refused attempt {a}, attempts used up",
                          "condition": _when(said_no)})
            for t in clone.get("transitions") or []:
                if t.get("target_node") == key:
                    t["target_node"] = step(i, a)
            if clone.get("max_turn_transition") == key:
                clone["max_turn_transition"] = step(i, a)
            clone["transitions"] = first + (clone.get("transitions") or [])
            clone["name"] = step(i, a)
            nodes[step(i, a)] = clone
    text = json.dumps(wf)
    if json.dumps(FIRST_ITEM) in text:
        wf.update(json.loads(text.replace(json.dumps(FIRST_ITEM), json.dumps(router(1)))))


ENGINE_VALUE = re.compile(r"^[A-Za-z_]\w*_(success_count|failure_count)$|^[A-Za-z_]\w*_response\.\S+$")
RULE_OPERATORS = ("equals", "not_equals", "greater_than", "less_than", "is_set", "is_not_set")


def check_precedence(rules: list, closings: dict, body: dict, base: Path) -> list[str]:
    problems = []
    mapped = {m.get("variable") for n in _all_nodes(body).values()
              for m in (n.get("response_mapping") or []) + [x for t in n.get("tools") or [] if isinstance(t, dict) for x in t.get("response_mapping") or []]}
    for k, rule in enumerate(rules if isinstance(rules, list) else []):
        cid = rule.get("closing")
        if cid not in closings:
            problems.append(f"precedence {k}: closing {cid!r} is not declared")
        for kept in rule.get("keep") or []:
            if kept not in closings:
                problems.append(f"precedence {k}: keep {kept!r} is not a declared closing")
        if not rule.get("when"):
            problems.append(f"precedence {k}: no checks in when")
        for c in rule.get("when") or []:
            name = str(c.get("variable") or "")
            if c.get("operator") not in RULE_OPERATORS:
                problems.append(f"precedence {k}: operator {c.get('operator')!r} is not one of {RULE_OPERATORS}")
            if not (ENGINE_VALUE.match(name) or name in mapped):
                problems.append(f"precedence {k}: {name!r} is not written by the engine from a tool result")
        quotes = _quotes(rule.get("evidence") or [], base)
        if not quotes or not all(quotes):
            problems.append(f"precedence {k}: every evidence quote must appear in its source")
    if not isinstance(rules, list):
        problems.append("precedence must be a list of rules")
    return problems


def router_name(closing_id: str) -> str:
    return "end_" + step_name(closing_id)[len("close_"):]


def terminal_tool(term: str, op: dict, fields: dict, values: dict) -> dict:
    body = {}
    for name in op["properties"]:
        if name in values:
            body[name] = {"type": "string", "default": values[name]}
            if op["properties"][name].get("enum"):
                body[name]["enum"] = [values[name]]
        elif name in fields:
            body[name] = {"type": "string", "default": fields[name]}
    url = (op["servers"][0] if op["servers"] else "") + op["path"]
    return {"type": "function", "config": dict(TERMINAL_CONFIG), "function": {
        "name": term, "handler": "__function__:api_call", "description": "Record how the call ended.",
        "parameters": {"type": "object", "properties": {
            "url": {"type": "string", "default": url}, "method": {"type": "string", "default": op["method"]},
            "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
            "body": {"type": "object", "properties": body, "required": []}}}}}


def _targets(node: dict):
    """Every place a step names another step, as (container, key)."""
    for t in node.get("transitions") or []:
        if isinstance(t, dict) and "target_node" in t:
            yield t, "target_node"
    for f in ("passthrough_default_transition", "max_turn_transition"):
        if f in node:
            yield node, f


def lower(body: dict, plan: dict, openapi: dict, base: Path = Path(".")) -> tuple[dict, dict]:
    """(workflow, contract) for BODY with PLAN's endings written in. Raises LoweringError."""
    ops = load_operations(openapi)
    problems = check_plan(plan, ops, base)
    term = (plan.get("terminal") or {}).get("tool")
    wf = copy.deepcopy(body)
    ladder = plan.get("ladder")
    if ladder:
        found = check_ladder(ladder, body, base)
        if found:
            raise LoweringError(problems + found)
        expand_ladder(wf, ladder)
    if NEXT_ITEM in json.dumps(wf) or FIRST_ITEM in json.dumps(wf):
        problems.append(f"{NEXT_ITEM} and {FIRST_ITEM} need a ladder in the plan, entered from outside its template")
    nodes = wf.get("nodes") or {}
    for key, node in _all_nodes(wf).items():
        if node.get("node_type") == "end_call":
            problems.append(f"step {key!r} is an end_call step; endings are declared in the plan, not written")
        for field in ("tools", "pre_actions"):
            if any(isinstance(t, dict) and tool_operation(t, ops) == term for t in node.get(field) or []):
                problems.append(f"step {key!r} offers or runs the terminal tool {term}; route to a declared closing instead")
    closings = plan.get("closings") or {}
    rules = plan.get("precedence") or []
    problems += check_precedence(rules, closings, body, base)

    def overriding(cid):
        return [r for r in rules if isinstance(r, dict) and r.get("closing") != cid and cid not in (r.get("keep") or [])]

    used = []
    for key, node in _all_nodes(wf).items():
        for holder, field in _targets(node):
            target = str(holder.get(field) or "")
            if target.startswith(SYMBOL):
                cid = target[len(SYMBOL):]
                if cid not in closings:
                    problems.append(f"step {key!r} routes to undeclared closing {cid!r}")
                    continue
                holder[field] = router_name(cid) if rules and overriding(cid) else step_name(cid)
                used.append(cid)
    referenced = set(used)
    used += [r.get("closing") for r in rules if isinstance(r, dict) and r.get("closing") in closings and used]
    taken = {step_name(c) for c in closings} | {router_name(c) for c in closings} | {END_STEP}
    clash = sorted(taken & set(_all_nodes(body)))
    if clash:
        problems.append(f"body steps {clash} use names the lowering writes")
    if not used:
        problems.append("no step routes to a closing")
    if problems:
        raise LoweringError(problems)
    op = ops[term]
    for cid in sorted(set(used)):
        nodes[step_name(cid)] = {
            "name": step_name(cid), "node_type": "api_request", "passthrough": True,
            "passthrough_default_transition": END_STEP, "disable_inactivity_monitor": True,
            "on_enter": {"type": "tts", "text": closings[cid]["say"]} if closings[cid].get("say") else {"type": "silent"},
            "pre_actions": [terminal_tool(term, op, plan.get("fields") or {}, closings[cid].get("set") or {})],
            "response_mapping": [], "transitions": [{"target_node": END_STEP, "description": "always", "condition": {"operator": "always"}}]}
        if rules and overriding(cid) and cid in referenced:
            nodes[router_name(cid)] = {
                "name": router_name(cid), "node_type": "conversation", "passthrough": True, "passthrough_default_transition": step_name(cid),
                "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True, "task_message": "Do not call a tool in this turn.",
                "transitions": [{"target_node": step_name(r["closing"]), "description": f"the tool results decide {r['closing']}",
                                 "condition": {"logic": "or", "conditions": [{"logic": "and", "conditions": [dict(c) for c in r["when"]]}]}}
                                for r in overriding(cid)]
                + [{"target_node": step_name(cid), "description": "always", "condition": {"operator": "always"}}]}
    nodes[END_STEP] = {"name": END_STEP, "node_type": "end_call", "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
                       "transitions": [], "terminal": {"type": "function", "function": {
                           "name": "call_closed", "handler": "__function__:end_call",
                           "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}}}
    contract = {"terminal_tools": [{"tool": term, "evidence": plan["terminal"]["evidence"]}], "every_call_ends_with_terminal": True}
    return wf, contract


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    p.add_argument("body", type=Path)
    p.add_argument("plan", type=Path)
    p.add_argument("--tools", type=Path, required=True)
    p.add_argument("--base", type=Path, default=Path("."), help="directory that evidence sources are relative to")
    p.add_argument("-o", "--out", type=Path)
    p.add_argument("--contract", type=Path, help="also write the terminal contract for workflow_check")
    a = p.parse_args(argv)
    try:
        body, plan, api = (json.loads(x.read_text()) for x in (a.body, a.plan, a.tools))
    except (OSError, ValueError) as e:
        print(f"cannot read input: {e}", file=sys.stderr)
        return 2
    try:
        wf, contract = lower(body, plan, api, a.base)
    except LoweringError as e:
        for problem in e.problems:
            print("REJECTED", problem)
        return 1
    text = json.dumps(wf, indent=1, ensure_ascii=False) + "\n"
    if a.out:
        a.out.write_text(text)
    else:
        sys.stdout.write(text)
    if a.contract:
        a.contract.write_text(json.dumps(contract, indent=1) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())

def bank_ops(node: dict, ops: dict[str, dict]) -> list[str]:
    tools = (node.get("tools") or []) + (node.get("pre_actions") or [])
    return [o for o in (tool_operation(t, ops) for t in tools if isinstance(t, dict)) if o]


def check_graph(wf: dict, exported: bool = False) -> list[Finding]:
    out = []
    if "agent_config" in wf and not exported:
        out.append(Finding("warning", "W-AGENT-CONFIG", "agent_config", "leave agent_config out; freya.py sets the event model"))
    nodes = _all_nodes(wf)
    if wf.get("initial_node") not in (wf.get("nodes") or {}):
        out.append(Finding("error", "E-REF", "initial_node", f"{wf.get('initial_node')!r} is not a step"))
    for key, node in nodes.items():
        kind = node.get("node_type")
        for t in node.get("transitions") or []:
            target = t.get("target_node") if isinstance(t, dict) else None
            if target not in nodes and not (target == "__previous__" and key in (wf.get("global_nodes") or {})):
                out.append(Finding("error", "E-REF", key, f"transition to unknown step {target!r}"))
        for f in ("passthrough_default_transition", "max_turn_transition"):
            if node.get(f) and node[f] not in nodes and node[f] != "__previous__":
                out.append(Finding("error", "E-REF", key, f"{f} is unknown step {node[f]!r}"))
        if node.get("tools") and kind != "conversation":
            out.append(Finding("error", "E-PLACEMENT", key, f"tools on a {kind} step are removed by the platform"))
        if node.get("pre_actions") and kind == "conversation":
            out.append(Finding("error", "E-PLACEMENT", key, "pre_actions on a conversation step are removed by the platform"))
        if node.get("passthrough"):
            last = (node.get("transitions") or [{}])[-1]
            if ((last or {}).get("condition") or {}).get("operator") != "always":
                out.append(Finding("error", "E-PASSTHROUGH", key, "a passthrough step must end with an always transition, or it can deadlock"))
        if kind == "end_call" and (node.get("transitions") or node.get("tools")):
            out.append(Finding("error", "E-END", key, "an end_call step has no transitions and no tools"))
        if node.get("max_node_turns") and not node.get("max_turn_transition"):
            out.append(Finding("warning", "W-TURN-CAP", key, "max_node_turns without max_turn_transition changes nothing at the cap"))
        for t in node.get("pre_actions") or []:
            code = str(_default(((t.get("function") or {}).get("parameters") or {}).get("properties", {}).get("code")) or "")
            if "{{" in code or "}}" in code:
                out.append(Finding("error", "E-CODE-BRACES", key, "code contains {{ or }}; read values from vars instead"))
    for path in ([] if exported else _null_paths(wf, "$")):
        out.append(Finding("error", "E-NULL", path, "null values fail the platform's validation"))
    graph = edges(wf)
    ends = {k for k, n in nodes.items() if n.get("node_type") == "end_call"}
    for key in nodes:
        if key not in ends and not _reach(graph, key) & ends:
            out.append(Finding("warning", "W-NO-END", key, "no path from this step reaches an end_call step"))
    start = wf.get("initial_node")
    if start in nodes:
        reached = _reach(graph, start) | {start}
        for key in sorted(set(wf.get("nodes") or {}) - reached):
            out.append(Finding("warning", "W-UNREACHABLE", key, f"no path from {start!r} enters this step"))
    return out


def _null_paths(value, path):
    if value is None:
        yield path
    elif isinstance(value, dict):
        for k, v in value.items():
            yield from _null_paths(v, f"{path}.{k}")
    elif isinstance(value, list):
        for i, v in enumerate(value):
            yield from _null_paths(v, f"{path}[{i}]")


def _reach(graph: dict[str, set[str]], start: str) -> set[str]:
    seen, queue = set(), deque(graph.get(start, ()))
    while queue:
        k = queue.popleft()
        if k in seen:
            continue
        seen.add(k)
        queue.extend(graph.get(k, ()))
    return seen


# ---------------------------------------------------------------- terminal actions

def check_contract(contract: dict, ops: dict[str, dict], base: Path) -> list[Finding]:
    out = []
    terminals = contract.get("terminal_tools") or []
    if not terminals:
        out.append(Finding("warning", "W-NO-TERMINAL", "contract", "no terminal tool declared; check the tool API and the brief"))
    for t in terminals:
        name = t.get("tool")
        if name not in ops:
            out.append(Finding("error", "E-CONTRACT-TOOL", "contract", f"terminal tool {name!r} is not an operation of the tool API"))
        if not t.get("evidence"):
            out.append(Finding("error", "E-CONTRACT-EVIDENCE", "contract", f"terminal tool {name!r} has no evidence"))
        for ev in t.get("evidence") or []:
            src = base / str(ev.get("source", ""))
            quote = " ".join(str(ev.get("quote", "")).split())
            text = " ".join(src.read_text(errors="replace").split()) if src.is_file() else ""
            if not quote or quote not in text:
                out.append(Finding("error", "E-CONTRACT-EVIDENCE", "contract", f"quote for {name!r} not found in {ev.get('source')}: {quote[:80]!r}"))
    return out


def check_terminal(wf: dict, ops: dict[str, dict], contract: dict) -> list[Finding]:
    out = []
    terminal = {t.get("tool") for t in contract.get("terminal_tools") or []}
    if not terminal:
        return out
    nodes = _all_nodes(wf)
    graph = edges(wf)
    term_nodes = set()
    for key, node in nodes.items():
        for field in ("tools", "pre_actions"):
            used = [o for o in (tool_operation(t, ops) for t in node.get(field) or [] if isinstance(t, dict)) if o]
            hit = set(used) & terminal
            if hit:
                term_nodes.add(key)
                others = sorted(set(used) - hit)
                if others:
                    out.append(Finding("error", "E-TERMINAL-SHARED", key,
                                       f"{sorted(hit)} is offered together with {others}; tool calls of one message run concurrently, so the terminal call can land first"))
    if not term_nodes:
        out.append(Finding("error", "E-TERMINAL-MISSING", "workflow", f"no step offers or runs the terminal tool {sorted(terminal)}"))
    for t in term_nodes:
        for r in sorted(_reach(graph, t) - {t}):
            later = sorted(set(bank_ops(nodes[r], ops)) - terminal)
            if later:
                out.append(Finding("error", "E-TERMINAL-AFTER", r, f"reachable from terminal step {t!r} and offers or runs {later}; a terminal step may lead only to end_call steps"))
    for tool in wf.get("tools") or []:
        if "end_of_call" in ((tool.get("config") or {}).get("alwaysRunsAt") or []) and tool_operation(tool, ops):
            out.append(Finding("error", "E-TERMINAL-AFTER", "tools", f"end-of-call lifecycle tool {tool['function'].get('name')} calls the bank after the call"))
    if contract.get("every_call_ends_with_terminal"):
        ends = {k for k, n in nodes.items() if n.get("node_type") == "end_call"}
        if wf.get("initial_node") in ends:
            out.append(Finding("error", "E-TERMINAL-BYPASS", wf["initial_node"], "the call can end without the terminal tool"))
        for src, targets in graph.items():
            for e in sorted(targets & ends):
                if src not in term_nodes:
                    out.append(Finding("error", "E-TERMINAL-BYPASS", src, f"enters end_call step {e!r} without passing a terminal step"))
    return out


# ---------------------------------------------------------------- bounded execution
#
# A passthrough step routes right after its entry actions, without a customer message. A loop made only of such
# steps runs as fast as the engine can go. The kit's counters (tools-and-code.md, "Success and failure counters")
# give a bound that needs no code: every run of an action step adds one to <step>_success_count or to
# <step>_failure_count. A loop is bounded when, somewhere on it, both counters of one action step on it are capped.

COUNTER = re.compile(r"^(?P<step>.+)_(?P<kind>success|failure)_count$")
CYCLE_LIMIT = 2000


def _alternatives(cond) -> list[list[dict]]:
    """A condition as OR-alternatives, each a list of plain checks that must all hold. [[]] means always."""
    if not isinstance(cond, dict) or cond.get("operator") == "always":
        return [[]]
    if "conditions" in cond:
        parts = [_alternatives(c) for c in cond.get("conditions") or []]
        if cond.get("logic") == "and":
            out = [[]]
            for alts in parts:
                out = [a + b for a in out for b in alts]
            return out
        return [alt for alts in parts for alt in alts]
    return [[cond]]


def _counter_check(check: dict, operator: str):
    m = COUNTER.match(str(check.get("variable") or ""))
    if not m or check.get("operator") != operator:
        return None
    try:
        return (m["step"], m["kind"]), float(check.get("operand"))
    except (TypeError, ValueError):
        return None


def _routes(node: dict) -> list[tuple[int, str, list[list[dict]]]]:
    """How a passthrough step routes: (position, target, alternatives) in evaluation order, up to the first always."""
    out = []
    for i, t in enumerate(node.get("transitions") or []):
        if not isinstance(t, dict) or not t.get("target_node") or t.get("is_tool_call"):
            continue
        alts = _alternatives(t.get("condition"))
        out.append((i, t["target_node"], alts))
        if [] in alts:
            return out
    if node.get("passthrough_default_transition"):
        out.append((len(node.get("transitions") or []), node["passthrough_default_transition"], [[]]))
    return out


def engine_edges(wf: dict) -> dict[str, dict[str, tuple[int, set]]]:
    """Edges the engine can take without a customer message: from passthrough steps only. For each edge, the
    position of its first transition and the counters that every one of its alternatives requires to stay below a
    limit (transitions to one target are merged by the engine, so their alternatives are pooled)."""
    nodes = _all_nodes(wf)
    out: dict[str, dict[str, tuple[int, set]]] = {}
    for key, node in nodes.items():
        if not node.get("passthrough"):
            continue
        pooled: dict[str, list] = {}
        first: dict[str, int] = {}
        for i, target, alts in _routes(node):
            if target in nodes:
                pooled.setdefault(target, []).extend(alts)
                first.setdefault(target, i)
        out[key] = {}
        for target, alts in pooled.items():
            gated = None
            for alt in alts:
                below = {c[0]: c[1] for c in (_counter_check(x, "less_than") for x in alt) if c}
                gated = below if gated is None else {c: max(gated[c], below[c]) for c in gated if c in below}
            out[key][target] = (first[target], set((gated or {}).items()))
    return out


def _sccs(graph: dict[str, set[str]]) -> list[set[str]]:
    """Strongly connected components with a cycle (Tarjan)."""
    index, low, stack, on, out, counter = {}, {}, [], set(), [], [0]

    def visit(v):
        index[v] = low[v] = counter[0]
        counter[0] += 1
        stack.append(v)
        on.add(v)
        for w in sorted(graph.get(v, ())):
            if w not in index:
                visit(w)
                low[v] = min(low[v], low[w])
            elif w in on:
                low[v] = min(low[v], index[w])
        if low[v] == index[v]:
            comp = set()
            while True:
                w = stack.pop()
                on.discard(w)
                comp.add(w)
                if w == v:
                    break
            if len(comp) > 1 or v in graph.get(v, ()):
                out.append(comp)

    for v in sorted(graph):
        if v not in index:
            visit(v)
    return out


def _simple_cycles(graph: dict[str, set[str]], comp: set[str], limit: int = CYCLE_LIMIT) -> list[list[str]] | None:
    """Every simple cycle inside one component, or None when there are more than the limit."""
    order = sorted(comp)
    found: list[list[str]] = []

    def walk(start, v, path, allowed):
        for w in sorted(graph.get(v, ()) & allowed):
            if w == start:
                found.append(list(path))
                if len(found) > limit:
                    raise OverflowError
            elif w not in path:
                path.append(w)
                walk(start, w, path, allowed)
                path.pop()

    try:
        for i, s in enumerate(order):
            walk(s, s, [s], set(order[i:]))
    except OverflowError:
        return None
    return found


def _cycle_bound(cycle: list[str], comp: set[str], nodes: dict, eng: dict) -> tuple[str, int] | None:
    """(step, most runs of that step) when the engine's counters bound this cycle, else None."""
    capped: dict[tuple[str, str], float] = {}

    def cap(counter, most):
        capped[counter] = min(capped.get(counter, most), most)

    for i, g in enumerate(cycle):
        nxt = cycle[(i + 1) % len(cycle)]
        position, gated = eng[g][nxt]
        for counter, limit in gated:
            cap(counter, limit - 1)
        for j, target, alts in _routes(nodes[g]):
            if j >= position:
                break
            if target in comp:
                continue
            for alt in alts:
                c = _counter_check(alt[0], "greater_than") if len(alt) == 1 else None
                if c:
                    cap(c[0], c[1])
    for step in cycle:
        if not nodes[step].get("pre_actions"):
            continue
        s, f = capped.get((step, "success")), capped.get((step, "failure"))
        if s is not None and f is not None:
            return step, int(max(s, 0) + max(f, 0) + 1)
    return None


def _is_code(tool: dict) -> bool:
    return (tool.get("function") or {}).get("handler") == "__function__:code_exec"


def _hooked(tool: dict) -> bool:
    return any(str(tool.get(h) or "").strip() for h in ("pre_process_code", "post_process_code"))


def _actions(node: dict, ops: dict[str, dict]) -> list[str]:
    """What one run of a step sends: code_exec runs and bank operations."""
    out = []
    for t in node.get("pre_actions") or []:
        if isinstance(t, dict):
            out.append("code_exec (sandbox)" if _is_code(t) else (tool_operation(t, ops) or "?") + " (bank)")
    return out


def check_execution(wf: dict, ops: dict[str, dict]) -> list[Finding]:
    out = []
    nodes = _all_nodes(wf)
    eng = engine_edges(wf)
    graph = {k: set(v) for k, v in eng.items()}
    for comp in _sccs(graph):
        cycles = _simple_cycles(graph, comp)
        where = sorted(comp)[0]
        if cycles is None:
            out.append(Finding("warning", "W-LOOP-UNCHECKED", where, f"steps {sorted(comp)} route among themselves without a customer message in more than {CYCLE_LIMIT} ways; their bound was not checked"))
            continue
        unbounded, bounds = [], []
        for cyc in cycles:
            b = _cycle_bound(cyc, comp, nodes, eng)
            if b:
                bounds.append((cyc, b))
            else:
                unbounded.append(cyc)
        for cyc in unbounded[:3]:
            runs = "; ".join(f"{s}: {', '.join(_actions(nodes[s], ops)) or 'no action'}" for s in cyc)
            out.append(Finding("error", "E-ENGINE-LOOP", cyc[0],
                               f"{' -> '.join(cyc + [cyc[0]])} routes without a customer message and has no engine bound: no exit on, "
                               f"or stay condition below, both <step>_success_count and <step>_failure_count of an action step on it. "
                               f"Variables written by code do not count; a failed sandbox call leaves them unchanged. Each pass runs {runs}"))
        for cyc, (step, most) in bounds:
            bank = sorted({o for s in cyc for o in bank_ops(nodes[s], ops)})
            if bank:
                out.append(Finding("warning", "W-LOOP-WRITE", cyc[0],
                                   f"{' -> '.join(cyc + [cyc[0]])} can send {bank} more than once in one call; a pass after an unknown outcome "
                                   f"sends the request again. Assumed bound, not proven: {step} runs at most about {most} times if every run adds "
                                   f"to its success or failure counter as documented (failure counters not yet observed)"))
    return out


def sandbox_exposure(wf: dict, ops: dict[str, dict]) -> dict:
    """How many runtime parts of the workflow need the Python sandbox. A hook on a bank tool is the costly kind: when
    the sandbox fails after the bank accepted the request, the workflow sees a failure (docs/PLATFORM_NOTES.md)."""
    nodes = _all_nodes(wf)
    eng_loops = set().union(*_sccs({k: set(v) for k, v in engine_edges(wf).items()}) or [set()])
    code_steps = sorted(k for k, n in nodes.items() if any(_is_code(t) for t in n.get("pre_actions") or [] if isinstance(t, dict)))
    offered = [t for n in nodes.values() for t in n.get("tools") or [] if isinstance(t, dict)]
    lifecycle = [t for t in wf.get("tools") or [] if isinstance(t, dict)]
    actions = [t for n in nodes.values() for t in n.get("pre_actions") or [] if isinstance(t, dict)]
    every = offered + lifecycle + actions
    return {
        "code_steps": len(code_steps),
        "code_tools": sum(1 for t in offered + lifecycle if _is_code(t)),
        "hooks": sum(1 for t in every if _hooked(t)),
        "hooks_on_bank_tools": sum(1 for t in every if _hooked(t) and tool_operation(t, ops)),
        "code_steps_in_engine_loops": sum(1 for k in code_steps if k in eng_loops),
    }


